function windowScroll() {
    const navbar = document.getElementById("navbar-sticky");
    const navbarpassticky = document.getElementById("navbarpas-sticky");
    if (navbar) {
        if (document.body.scrollTop >= 50 || document.documentElement.scrollTop >= 50) {
            // Ajout des classes lorsque l'utilisateur défile
            navbar.classList.add("dark:bg-gray-800");
            navbar.classList.add("bg-white");
            navbar.classList.add("nav-sticky");
        } else {
            // Suppression des classes lorsque l'utilisateur est en haut de la page
            navbar.classList.remove("dark:bg-gray-800");
            navbar.classList.remove("bg-white");
            navbar.classList.remove("nav-sticky");
        }
    }
    if(navbarpassticky) {
        if (document.body.scrollTop >= 50 || document.documentElement.scrollTop >= 50) {
            // Ajout des classes lorsque l'utilisateur défile
        } else {
            // Suppression des classes lorsque l'utilisateur est en haut de la page
        }        
    }
}

// Initialisation et écoute de l'événement scroll
window.addEventListener("scroll", (t) => {
    t.preventDefault();
    windowScroll();
});

// Autres fonctionnalités (restant inchangées)
lucide.createIcons();
var spy = new Gumshoe("#navbar-navlist a", { offset: 80 });

function scrollFunction() {
    var t = document.getElementById("back-to-top");
    if (t) {
        if (document.body.scrollTop > 500 || document.documentElement.scrollTop > 500) {
            t.classList.add("opacity-100");
            t.classList.remove("opacity-0");
        } else {
            t.classList.add("opacity-0");
            t.classList.remove("opacity-100");
        }
    }
}

function topFunction() {
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;
}

function init() {
    window.onload = function () {
        function TypeWriter(el, toRotate, period) {
            this.toRotate = toRotate;
            this.el = el;
            this.loopNum = 0;
            this.period = parseInt(period, 10) || 2000;
            this.txt = "";
            this.tick();
            this.isDeleting = false;
        }

        TypeWriter.prototype.tick = function () {
            const fullTxt = this.toRotate[this.loopNum % this.toRotate.length];
            if (this.isDeleting) {
                this.txt = fullTxt.substring(0, this.txt.length - 1);
            } else {
                this.txt = fullTxt.substring(0, this.txt.length + 1);
            }

            this.el.innerHTML = '<span class="text-wrap">' + this.txt + "</span>";

            let delta = 200 - Math.random() * 100;
            if (this.isDeleting) {
                delta /= 2;
            }

            if (!this.isDeleting && this.txt === fullTxt) {
                delta = this.period;
                this.isDeleting = true;
            } else if (this.isDeleting && this.txt === "") {
                this.isDeleting = false;
                this.loopNum++;
                delta = 500;
            }

            setTimeout(() => {
                this.tick();
            }, delta);
        };

        const elements = document.getElementsByClassName("typewrite");
        for (let i = 0; i < elements.length; i++) {
            const toRotate = elements[i].getAttribute("data-type");
            const period = elements[i].getAttribute("data-period");
            if (toRotate) {
                new TypeWriter(elements[i], JSON.parse(toRotate), period);
            }
        }
    };
}

window.onscroll = function () {
    scrollFunction();
};

init();
